int n;
int a[200005],b[200005];
int bb[30][200005];

int main(){
	scanf("%d",&n);
	for(int i=0;i<n;i++){
		scanf("%d",a+i);
	}
	for(int i=0;i<n;i++){
		scanf("%d",b+i);
		for(int j=0,msk=1;j<30;j++,(msk<<=1)|=1){
			bb[j][i]=b[i]&msk;
		}
	}
	for(int i=0;i<30;i++){
		sort(bb[i],bb[i]+n);
	}
	int ans=0;
	for(int i=0,msk=1;i<30;i++,(msk<<=1)|=1){
		long long cnt=0;
		for(int j=0;j<n;j++){
			if(!(a[j]&(1<<i))){
				int maxx=(1<<(i+1))-(a[j]&msk),minx=(1<<i)-(a[j]&msk);
				cnt+=lower_bound(bb[i],bb[i]+n,maxx)-lower_bound(bb[i],bb[i]+n,minx);
				//cerr<<i<<' '<<cnt<<' '<<maxx<<' '<<minx<<endl;
			}else{
				int maxx=(1<<(i+1))-(a[j]&msk),minx=(1<<(i+1))-(a[j]&msk)+(1<<i);
				cnt+=lower_bound(bb[i],bb[i]+n,maxx)-bb[i];
				cnt+=n+bb[i]-lower_bound(bb[i],bb[i]+n,minx);
				//cerr<<i<<' '<<cnt<<' '<<maxx<<' '<<minx<<endl;
			}
		}
		//cerr<<i<<' '<<cnt<<endl;
		if(cnt&1){
			ans|=(1<<i);
		}
	}
	printf("%d\n",ans);
	return 0;
}
